B.a7D=new A.es("k1",B.c2,"Nguy\xean l\xfd bi \u1ea3o (Ghost Ball)","Bi \u1ea3o l\xe0 v\u1ecb tr\xed t\u01b0\u1edfng t\u01b0\u1ee3ng c\u1ee7a bi c\xe1i ngay tr\u01b0\u1edbc khi n\xf3 ch\u1ea1m bi m\u1ee5c ti\xeau. Mu\u1ed1n bi m\u1ee5c ti\xeau \u0111i \u0111\xfang h\u01b0\u1edbng t\u1edbi l\u1ed7, t\xe2m bi c\xe1i ph\u1ea3i \u0111i t\u1edbi \u0111\xfang t\xe2m c\u1ee7a bi \u1ea3o \u0111\xf3. C\xe1ch luy\u1ec7n: nh\xecn \u0111\u01b0\u1eddng th\u1eb3ng t\u1eeb l\u1ed7 qua t\xe2m bi m\u1ee5c ti\xeau, k\xe9o d\xe0i th\xeam m\u1ed9t \u0111\u01b0\u1eddng k\xednh bi ra ph\xeda sau \u2014 \u0111\xf3 ch\xednh l\xe0 t\xe2m bi \u1ea3o c\u1ea7n ng\u1eafm t\u1edbi.",B.afc)
B.afa=s(["d1"],t.s)
B.a7A=new A.es("k2",B.c2,"C\xe1ch c\u1ea7m c\u01a1 v\xe0 t\u01b0 th\u1ebf chu\u1ea9n","Tay c\u1ea7m c\u01a1 n\xean th\u1ea3 l\u1ecfng, ch\u1ec9 si\u1ebft nh\u1eb9 khi ti\u1ebfp x\xfac bi. C\xe1nh tay tr\xean vu\xf4ng g\xf3c v\u1edbi c\u1eb3ng tay \u1edf \u0111i\u1ec3m ng\u1eafm cu\u1ed1i c\xf9ng. M\u1eaft n\xean \u0111\u1eb7t th\u1eb3ng tr\xean \u0111\u01b0\u1eddng c\u01a1 \u0111\u1ec3 nh\xecn \u0111\u01b0\u1ee3c c\u1ea3 bi c\xe1i v\xe0 bi m\u1ee5c ti\xeau c\xf9ng l\xfac. Gi\u1eef \u0111\u1ea7u c\u1ed1 \u0111\u1ecbnh trong su\u1ed1t c\xfa \u0111\xe1nh \u2014 ph\u1ea7n l\u1edbn l\u1ed7i ng\u1eafm \u0111\u1ebfn t\u1eeb vi\u1ec7c \u0111\u1ea7u di chuy\u1ec3n tr\u01b0\u1edbc khi c\u01a1 ch\u1ea1m bi.",B.afa)
B.afd=s(["d3","d4","d5"],t.s)
B.a7E=new A.es("k3",B.bC,"Nguy\xean t\u1eafc \u0111i\u1ec1u bi c\u01a1 b\u1ea3n (Position Play)",'Tr\u01b0\u1edbc m\u1ed7i c\xfa \u0111\xe1nh, h\xe3y ngh\u0129 t\u1edbi bi ti\u1ebfp theo tr\u01b0\u1edbc khi \u0111\xe1nh bi hi\u1ec7n t\u1ea1i. Ba y\u1ebfu t\u1ed1 ki\u1ec3m so\xe1t v\u1ecb tr\xed bi c\xe1i: \u0111i\u1ec3m ti\u1ebfp x\xfac tr\xean bi c\xe1i (tr\xean/gi\u1eefa/d\u01b0\u1edbi), l\u1ef1c \u0111\xe1nh, v\xe0 g\xf3c c\u1eaft. \u01afu ti\xean d\xf9ng l\u1ef1c nh\u1ecf nh\u1ea5t c\xf3 th\u1ec3 \u0111\u1ec3 gi\u1ea3m sai s\u1ed1 \u2014 \u0111i\u1ec1u bi b\u1eb1ng "t\u1ed1c \u0111\u1ed9" d\u1ec5 ki\u1ec3m so\xe1t h\u01a1n \u0111i\u1ec1u bi b\u1eb1ng "g\xf3c".',B.afd)
B.afe=s(["d6"],t.s)
B.a7F=new A.es("k4",B.fa,"Ph\xe1 hi\u1ec7u qu\u1ea3 trong Pool","M\u1ed9t c\xfa ph\xe1 t\u1ed1t c\u1ea7n c\u1ea3 l\u1ef1c v\xe0 \u0111\u1ed9 ch\xednh x\xe1c. \u0110\u1eb7t bi c\xe1i h\u01a1i l\u1ec7ch t\xe2m \u0111\u1ec3 tr\xe1nh xo\xe1y ng\u01b0\u1ee3c kh\xf4ng ki\u1ec3m so\xe1t. \u0110\xe1nh v\xe0o bi \u0111\u1ea7u rack v\u1edbi l\u1ef1c t\u1ed1i \u0111a m\xe0 v\u1eabn gi\u1eef \u0111\u01b0\u1ee3c c\u01a1 th\u1eb3ng \u2014 ph\xe1 m\u1ea1nh nh\u01b0ng l\u1ec7ch h\u01b0\u1edbng th\u01b0\u1eddng k\xe9m hi\u1ec7u qu\u1ea3 h\u01a1n ph\xe1 v\u1eeba ph\u1ea3i v\xe0 ch\xednh x\xe1c.",B.afe)
B.afh=s(["d8","d9"],t.s)
B.a7C=new A.es("k5",B.hV,"Quy t\u1eafc g\xf3c ph\u1ea3n x\u1ea1 khi A b\u0103ng","Khi bi l\u0103n kh\xf4ng xo\xe1y ch\u1ea1m b\u0103ng, g\xf3c t\u1edbi g\u1ea7n b\u1eb1ng g\xf3c ph\u1ea3n x\u1ea1 (gi\u1ed1ng \xe1nh s\xe1ng ph\u1ea3n chi\u1ebfu g\u01b0\u01a1ng). Xo\xe1y s\u1ebd l\xe0m thay \u0111\u1ed5i g\xf3c n\xe0y \u2014 \u0111\xe1nh cu l\xea l\xe0m g\xf3c ph\u1ea3n x\u1ea1 h\u1eb9p h\u01a1n, \u0111\xe1nh tr\xf4 bi l\xe0m g\xf3c r\u1ed9ng h\u01a1n. Luy\u1ec7n t\u1eadp kh\xf4ng xo\xe1y tr\u01b0\u1edbc \u0111\u1ec3 n\u1eafm v\u1eefng g\xf3c c\u01a1 b\u1ea3n. Quy t\u1eafc n\xe0y d\xf9ng chung cho c\u1ea3 A b\u0103ng v\xe0 C\xe2n bi.",B.afh)
